  <script>
    // Booking form handler (mock)
    document.getElementById('booking').addEventListener('submit',function(e){
      e.preventDefault();
      const name = this.name.value || 'Guest';
      alert('Thanks, ' + name + '. A confirmation will arrive at the email provided.');
      this.reset();
    });

    // Aroma wheel interaction
    (function(){
      const wheel = document.getElementById('wheel');
      const desc = document.getElementById('noteDesc');
      const center = document.getElementById('centerLabel');
      const notes = {
        top:{title:'Top notes — first impression',text:'Bright and volatile: citrus, light herbs, and fresh greens. They evaporate quickly and set the initial tone.'},
        middle:{title:'Middle notes — the heart',text:'Floral and herbal tones that form the core of a scent. They linger after the top notes dissipate.'},
        base:{title:'Base notes — anchor',text:'Deeper, lasting molecules: woods, resins, and balsams that remain and ground a blend.'}
      };

      // Create clickable/touchable segments using overlay buttons
      const segs = [ {start:0,end:120,type:'top'},{start:120,end:240,type:'middle'},{start:240,end:360,type:'base'} ];
      segs.forEach(s=>{
        const btn = document.createElement('button');
        btn.setAttribute('aria-label',s.type+' notes');
        btn.style.position='absolute';
        btn.style.inset='0';
        btn.style.border='none';
        btn.style.background='transparent';
        btn.style.cursor='pointer';
        btn.style.borderRadius='50%';
        // capture angle via data
        btn.dataset.type = s.type;
        btn.addEventListener('mouseenter',onEnter);
        btn.addEventListener('click',onEnter);
        btn.addEventListener('touchstart',onEnter);
        wheel.appendChild(btn);
      });

      function onEnter(e){
        const type = e.currentTarget.dataset.type;
        center.textContent = notes[type].title.split(' — ')[0];
        desc.textContent = notes[type].text;
        // small visual cue
        wheel.style.boxShadow='inset 0 -30px 60px rgba(0,0,0,0.6), 0 10px 30px rgba(2,6,10,0.6)';
        setTimeout(()=>{wheel.style.boxShadow='inset 0 -20px 40px rgba(0,0,0,0.4)';},600);
      }

      // Legend hover
      document.querySelectorAll('.note').forEach(n=>{
        n.addEventListener('mouseenter',()=>{
          const t=n.dataset.type;
          desc.textContent = notes[t].text;
          center.textContent = notes[t].title.split(' — ')[0];
        });
      });

      // Reset on leave
      wheel.addEventListener('mouseleave',()=>{center.textContent='Notes';desc.textContent='Hover over a legend label or touch a wheel segment to see more about that family.'});
    })();
  </script>
